SET standard_conforming_strings = OFF;
DROP TABLE IF EXISTS "public"."capitals" CASCADE;
BEGIN;
CREATE TABLE "public"."capitals" ( "ogc_fid" SERIAL, CONSTRAINT "capitals_pk" PRIMARY KEY ("ogc_fid") );
SELECT AddGeometryColumn('public','capitals','wkb_geometry',4326,'POINT',2);
CREATE INDEX "capitals_wkb_geometry_geom_idx" ON "public"."capitals" USING GIST ("wkb_geometry");
ALTER TABLE "public"."capitals" ADD COLUMN "id" VARCHAR;
ALTER TABLE "public"."capitals" ADD COLUMN "country" VARCHAR;
ALTER TABLE "public"."capitals" ADD COLUMN "city" VARCHAR;
ALTER TABLE "public"."capitals" ADD COLUMN "tld" VARCHAR;
ALTER TABLE "public"."capitals" ADD COLUMN "iso3" VARCHAR;
ALTER TABLE "public"."capitals" ADD COLUMN "iso2" VARCHAR;
COMMIT;
